// Package constants tests — T-10 characterization (Phase 1).
//
// THE LAW (roadmap Phase 1 + task list standing orders): the Python
// characterization tests are ported FIRST, then the code; the goldens were
// GENERATED by running the unmodified Python reference app
// (assadigit/GitCurator @ 98f4fc7) via testdiff/goldens/dump_constants.py —
// never hand-typed. Regenerate with:
//
//	python3 testdiff/goldens/dump_constants.py
//
// The golden compare uses a Python-compatible canonical JSON encoding
// (json.dumps(sort_keys=True, ensure_ascii=False, indent=2) + newline):
// sorted object keys, two-space indent, raw UTF-8, no HTML escaping, and
// integral floats keep their ".0" (Python repr(2.0) == "2.0"; Go's
// encoding/json would print "2" — doc 05 §3 item 9/4 hotspot).
package constants

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// pyCanonical — the canonical dumper shared by every golden test in this
// file (promoted into internal/storage with T-12's write_config_file).
// ---------------------------------------------------------------------------

func pyCanonical(v any) string {
	var b bytes.Buffer
	pyEncode(&b, reflect.ValueOf(v), "")
	b.WriteByte('\n')
	return b.String()
}

func pyEncode(b *bytes.Buffer, v reflect.Value, indent string) {
	switch v.Kind() {
	case reflect.Invalid:
		b.WriteString("null")
	case reflect.Bool:
		if v.Bool() {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		b.WriteString(strconv.FormatInt(v.Int(), 10))
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		b.WriteString(strconv.FormatUint(v.Uint(), 10))
	case reflect.Float32, reflect.Float64:
		pyEncodeFloat(b, v.Float())
	case reflect.String:
		pyEncodeString(b, v.String())
	case reflect.Slice, reflect.Array:
		if v.Kind() == reflect.Slice && v.IsNil() {
			b.WriteString("null") // Python None; unused by our data but kept honest
			return
		}
		if v.Len() == 0 {
			b.WriteString("[]")
			return
		}
		inner := indent + "  "
		b.WriteString("[\n")
		for i := 0; i < v.Len(); i++ {
			b.WriteString(inner)
			pyEncode(b, v.Index(i), inner)
			if i != v.Len()-1 {
				b.WriteByte(',')
			}
			b.WriteByte('\n')
		}
		b.WriteString(indent + "]")
	case reflect.Map:
		if v.Len() == 0 {
			b.WriteString("{}")
			return
		}
		// Python json.dumps(sort_keys=True) sorts by code point; our keys
		// are ASCII, so a plain sort matches.
		keys := make([]string, 0, v.Len())
		for _, k := range v.MapKeys() {
			keys = append(keys, k.String())
		}
		sort.Strings(keys)
		inner := indent + "  "
		b.WriteString("{\n")
		for i, k := range keys {
			b.WriteString(inner)
			pyEncodeString(b, k)
			b.WriteString(": ")
			pyEncode(b, v.MapIndex(reflect.ValueOf(k)), inner)
			if i != len(keys)-1 {
				b.WriteByte(',')
			}
			b.WriteByte('\n')
		}
		b.WriteString(indent + "}")
	case reflect.Pointer:
		if v.IsNil() {
			b.WriteString("null")
			return
		}
		pyEncode(b, v.Elem(), indent)
	case reflect.Interface:
		pyEncode(b, v.Elem(), indent)
	default:
		panic("pyEncode: unsupported kind " + v.Kind().String())
	}
}

func pyEncodeFloat(b *bytes.Buffer, f float64) {
	s := strconv.FormatFloat(f, 'g', -1, 64)
	// Python repr keeps a decimal point on integral floats (2.0), Go's
	// shortest form drops it (2). Compensate (finite values only here).
	if !strings.ContainsAny(s, ".eE") && !strings.Contains(s, "Inf") && !strings.Contains(s, "NaN") {
		s += ".0"
	}
	b.WriteString(s)
}

func pyEncodeString(b *bytes.Buffer, s string) {
	// Mirror json.dumps(ensure_ascii=False): raw UTF-8, escape only the
	// JSON-mandated characters. Go's stock escaping of <, >, & (HTML mode)
	// is disabled by hand-rolling the string encoder.
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			if r < 0x20 {
				fmt.Fprintf(b, "\\u%04x", r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
}

// golden reads a testdata golden file (generated, never hand-typed).
func golden(t *testing.T, name string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_constants.py): %v", name, err)
	}
	return string(raw)
}

// ---------------------------------------------------------------------------
// Golden 1 — CONFIG_EXAMPLE (the defaults contract, spec-core-constants).
// ---------------------------------------------------------------------------

func TestConfigExampleGolden(t *testing.T) {
	got := pyCanonical(ConfigExample())
	want := golden(t, "config_example.golden.json")
	if got != want {
		t.Fatalf("CONFIG_EXAMPLE drifted from the Python golden.\n--- want (python) --\n%s\n--- got (go) --\n%s",
			want, got)
	}
}

// ConfigExample must return a fresh deep copy: Python consumers deep-copy it
// as their base (vaults_config load_config); mutation by one caller must
// never leak into another.
func TestConfigExampleDeepCopy(t *testing.T) {
	a := ConfigExample()
	a["telegram_api_id"] = 999
	a["proxy"].(map[string]any)["port"] = 1
	b := ConfigExample()
	if b["telegram_api_id"].(int) != 0 {
		t.Fatalf("ConfigExample() leaked a mutation across calls: telegram_api_id=%v", b["telegram_api_id"])
	}
	if b["proxy"].(map[string]any)["port"].(int) != 10808 {
		t.Fatalf("ConfigExample() leaked a nested mutation: proxy.port=%v", b["proxy"].(map[string]any)["port"])
	}
}

// ---------------------------------------------------------------------------
// Golden 2 — every other constants symbol (the symbols envelope).
// ---------------------------------------------------------------------------

// probe builds one resolve_taxonomy_path probe as a plain map (the canonical
// dumper sorts keys; only non-empty outcome keys are present, mirroring the
// generator's per-probe shape).
func probe(cfg any, returned, returnedRel string) map[string]any {
	m := map[string]any{"config": cfg}
	if returned != "" {
		m["returned"] = returned
	}
	if returnedRel != "" {
		m["returned_rel"] = returnedRel
	}
	return m
}

func symbolsEnvelope() map[string]any {
	var folders [][2]string
	for _, e := range CategoryFolders {
		folders = append(folders, [2]string{e.Key, e.Folder})
	}
	probes := []any{
		probe(nil, "", relForGolden(ResolveTaxonomyPath(nil))),
		probe(map[string]any{}, "", relForGolden(ResolveTaxonomyPath(map[string]any{}))),
		probe(map[string]any{"taxonomy_path": ""}, "", relForGolden(ResolveTaxonomyPath(map[string]any{"taxonomy_path": ""}))),
		probe(map[string]any{"taxonomy_path": "   "}, "", relForGolden(ResolveTaxonomyPath(map[string]any{"taxonomy_path": "   "}))),
		probe(map[string]any{"taxonomy_path": "/abs/override/x.md"}, ResolveTaxonomyPath(map[string]any{"taxonomy_path": "/abs/override/x.md"}), ""),
		probe(map[string]any{"taxonomy_path": "  /abs/override/y.md  "}, ResolveTaxonomyPath(map[string]any{"taxonomy_path": "  /abs/override/y.md  "}), ""),
	}
	scalars := map[string]string{
		"managed_by_gitcurator":     ManagedByGitcurator,
		"note_schema_version":       NoteSchemaVersion,
		"github_prompt_version":     GitHubPromptVersion,
		"ownership_banner":          OwnershipBanner,
		"expected_worker_version":   ExpectedWorkerVersion,
		"config_file_rel":           relForGolden(ConfigFile()),
		"default_taxonomy_path_rel": relForGolden(DefaultTaxonomyPath()),
	}
	return map[string]any{
		"schema":                   1,
		"category_folders_ordered": folders,
		"category_keys_ordered":    CategoryKeys,
		"colors":                   Colors,
		"scalars":                  scalars,
		"resolve_taxonomy_path":    probes,
		"default_system_prompt":    DefaultSystemPrompt,
	}
}

// relForGolden mirrors the generator's rel(): AppDir-relative with "/"
// separators (platform-stable golden).
func relForGolden(p string) string {
	rel, err := filepath.Rel(AppDir(), p)
	if err != nil {
		return p
	}
	return strings.ReplaceAll(rel, string(filepath.Separator), "/")
}

func TestSymbolsGolden(t *testing.T) {
	got := pyCanonical(symbolsEnvelope())
	want := golden(t, "symbols.golden.json")
	if got != want {
		t.Fatalf("symbols envelope drifted from the Python golden.\n--- want (python) --\n%s\n--- got (go) --\n%s",
			want, got)
	}
}

// ---------------------------------------------------------------------------
// Behavior tests (spec-core-constants §Tests: category translation).
// ---------------------------------------------------------------------------

func TestCategoryFolderTranslation(t *testing.T) {
	cases := []struct {
		key  string
		want string
	}{
		{"Agents", "AI-Domain/Agents"},
		{"Scraping", "Tools/Scraping"},
		{"Uncategorized", "Uncategorized"},
		{"Infrastructure/Cloud", "Infrastructure/Cloud"},
	}
	for _, c := range cases {
		got, ok := CategoryFolder(c.key)
		if !ok || got != c.want {
			t.Errorf("CategoryFolder(%q) = %q, ok=%v; want %q", c.key, got, ok, c.want)
		}
	}
	if got, ok := CategoryFolder("Nope"); ok {
		t.Errorf(`CategoryFolder("Nope") = %q, ok=true; want ok=false`, got)
	}
}

// CATEGORY_KEYS order is behavior (the classifier prompt embeds it) — pinned
// by the golden too; this is the human-readable restatement.
func TestCategoryKeysMatchFolderOrder(t *testing.T) {
	if len(CategoryKeys) != len(CategoryFolders) {
		t.Fatalf("CategoryKeys len %d != CategoryFolders len %d", len(CategoryKeys), len(CategoryFolders))
	}
	for i, e := range CategoryFolders {
		if CategoryKeys[i] != e.Key {
			t.Errorf("CategoryKeys[%d]=%q != folder key %q", i, CategoryKeys[i], e.Key)
		}
	}
}

// ---------------------------------------------------------------------------
// AppDir anchoring (spec-core-constants compat req 3: executable dir, with
// the additive GITCURATOR_HOME escape hatch for tests).
// ---------------------------------------------------------------------------

func TestAppDirAnchoring(t *testing.T) {
	t.Setenv("GITCURATOR_HOME", "")
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	wantDir := filepath.Dir(exe)
	if AppDir() != wantDir {
		t.Fatalf("AppDir() = %q; want executable dir %q", AppDir(), wantDir)
	}
	if want := filepath.Join(wantDir, "config.json"); ConfigFile() != want {
		t.Fatalf("ConfigFile() = %q; want %q", ConfigFile(), want)
	}
	if want := filepath.Join(wantDir, "taxonomy", "website-library-categories.md"); DefaultTaxonomyPath() != want {
		t.Fatalf("DefaultTaxonomyPath() = %q; want %q", DefaultTaxonomyPath(), want)
	}

	home := t.TempDir()
	t.Setenv("GITCURATOR_HOME", home)
	if AppDir() != home {
		t.Fatalf("AppDir() with GITCURATOR_HOME=%q = %q; want %q", home, AppDir(), home)
	}
	if got := ConfigFile(); got != filepath.Join(home, "config.json") {
		t.Fatalf("ConfigFile() under GITCURATOR_HOME = %q", got)
	}
}

// Sanity: the golden machinery itself (pyCanonical vs encoding/json on a
// benign subset) — guards against silent encoder drift.
func TestPyCanonicalFloats(t *testing.T) {
	cases := []struct {
		in   any
		want string
	}{
		{0.5, "0.5"},
		{2.0, "2.0"},
		{float64(5), "5.0"},
		{10808, "10808"},
		{true, "true"},
		{[]any{}, "[]"},
		{map[string]any{}, "{}"},
		{[]any{1, 2}, "[\n  1,\n  2\n]"},
	}
	for _, c := range cases {
		got := strings.TrimSuffix(pyCanonical(c.in), "\n")
		if got != c.want {
			t.Errorf("pyCanonical(%v) = %q; want %q", c.in, got, c.want)
		}
	}
	// The em-dash in OWNERSHIP_BANNER must stay raw UTF-8 (no \u escapes).
	if !strings.Contains(OwnershipBanner, "\u2014") {
		t.Errorf("OwnershipBanner lost its em-dash: %q", OwnershipBanner)
	}
	var stock bytes.Buffer
	enc := json.NewEncoder(&stock)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(OwnershipBanner)
	if !strings.Contains(stock.String(), "\u2014") {
		t.Error("unexpected: stock encoder escaped the em-dash")
	}
}
